static unsigned checks=0;
static void need(bool v,const char* s){++checks;if(!v)throw std::runtime_error(s);}
int main(){try{
 for(uint64_t seed=0;seed<300;++seed){auto p=b::make_plan(seed);need(b::valid(p),"valid ten encounters");unsigned seen=0;for(unsigned i=0;i<6;++i)seen|=1u<<unsigned(p.fights[i].family);need(seen==63,"all six families before random fights");need(p.fights[0].count==1&&!p.fights[0].genie_companion&&p.fights[9].members[0].red,"first alone and red final");b::Session s;need(s.begin("battle0250",p,true),"begin");need(!s.defeat({0,0,1,0x80010000,true,true,true,true}),"cannot finish before entry");uint32_t player=0x80010000;for(unsigned i=0;i<10;++i){need(s.enter_fight(b::room(p.fights[i].family),player),"same native player enters each arena");for(unsigned n=0;n<p.fights[i].count;++n){const auto a=0x80020000+i*0x1000+n*0x200;need(s.bind(n,a),"bind unique exact member");need(!s.bind(n,a),"same member cannot bind twice");auto receipt=b::NativeReceipt{i,n,100+i,a,true,true,true,true};auto bad=receipt;bad.actor+=4;need(!s.defeat(bad),"wrong identity rejected");bad=receipt;bad.causal_hit=false;need(!s.defeat(bad),"causal proof required");need(s.defeat(receipt),"strict native receipt");need(!s.defeat(receipt),"duplicate receipt rejected");if(n+1<p.fights[i].count)need(s.snapshot().phase==b::Phase::Fighting,"every companion must die");}need(s.snapshot().completed==i+1,"one victory per encounter");need(s.use_victory_pot(),"voluntary victory pot");if(i<9){need(s.snapshot().phase==b::Phase::ToRest,"no automatic new fight");need(!s.arrive_rest(player+4),"same player required in rest");need(s.arrive_rest(player),"native rest arrival");need(s.use_rest_pot(),"voluntary onward pot");}else need(s.snapshot().phase==b::Phase::Complete,"ten required for completion");}}
 b::Random random{8};b::Config c;auto one=b::encounter(1,b::Family::Candy,0,random,c);need(one.count==1&&!one.genie_companion,"first candy never genie");for(unsigned v=0;v<3;++v){auto f=b::encounter(3,b::Family::Fish,v,random,c);need(b::valid_fish(f)&&f.count==(v==0?3u:2u),"approved one/two/three-fish composition");for(unsigned member=0;member<(v==0?3u:v==1?2u:1u);++member)need(f.members[member].kind==0x4511&&f.members[member].hits==(v==0?1u:v==1?2u:f.members[member].hits),"jumping-only Fish use the configured per-member HP");if(v==2)need(f.members[0].hits>=2&&f.members[0].hits<=3&&f.members[1].hits==2&&(f.members[1].kind==0x4072||f.members[1].kind==0x4599),"single Fish has two/three HP and a two-HP genie/invisible companion");auto m=b::encounter(4,b::Family::Monsters,v,random,c);need(m.count==2&&m.no_flowers&&m.no_egg_blocks,"two monsters without flower or block");need(m.members[0].hits==(v==0?4:v==1?3:5),"monster variant native hp");}
 need(b::Config{}.reference_birds==2&&b::Config{}.bird_respawn_ms==8000,"Genie and Invisible default to two yellow birds with the existing eight-active-second respawn");
 for(bool custom:{false,true})for(auto family:{b::Family::Invisible,b::Family::Genie})for(unsigned variant=0;variant<3;++variant){
  b::Config supply;if(custom){supply.reference_birds=3;supply.more_birds=4;supply.bird_respawn_ms=5000;}need(supply.valid(),"Configured reference bird quota remains valid");
  b::Random source{0x175A+variant},expected=source;const unsigned terrain=expected.pick(3);const auto encounter=b::encounter(8,family,variant,source,supply);
  need(encounter.birds==supply.reference_birds&&encounter.bird_respawn_ms==supply.bird_respawn_ms,"Every Genie and Invisible variant delivers its configured yellow-bird quota and unchanged delay");
  need(source.state==expected.state&&encounter.terrain==terrain,"Adding required birds consumes no additional boss-plan RNG or terrain draw");
  const unsigned count=variant==0?1:variant==1?2:4,hits=variant==0?3:variant==1?2:1;need(encounter.count==count&&!encounter.genie_companion&&!encounter.purple_mask&&!encounter.no_flowers&&!encounter.no_egg_blocks,"Reference supply changes no native roster or encounter rules");
  for(unsigned n=0;n<count;++n){const auto& member=encounter.members[n];need(member.kind==(family==b::Family::Genie?0x4072:0x4599)&&member.hits==hits&&member.scale==1&&!member.red&&!member.purple&&!member.green,"Genie and Invisible member HP, kind, scale and colors remain unchanged");}
 }
 for(auto family:{b::Family::Invisible,b::Family::Genie})for(unsigned fault=0;fault<3;++fault){auto tampered=b::make_plan(1);bool found=false;for(auto& fight:tampered.fights)if(fight.family==family){if(fault==0)fight.birds=0;if(fault==1)++fight.birds;if(fault==2)++fight.bird_respawn_ms;found=true;break;}need(found&&!b::valid(tampered),"Missing or altered Genie/Invisible quota or respawn cannot pass campaign validation");}
 {auto changed=b::make_plan(1);bool found=false;for(auto& fight:changed.fights)if(fight.family==b::Family::Fish){fight.members[0].hits=4;found=true;break;}need(found&&!b::valid(changed),"four-HP Fish are outside every approved balance variant");}
 need(b::Config{}.fish_birds==3&&b::Config{}.fish_respawn_ms==3000,"Fish defaults provide three birds every three active seconds");
 for(unsigned quota:{1u,2u,3u})for(unsigned delay:{1000u,3000u,60000u}){b::Config custom;custom.fish_birds=quota;custom.fish_respawn_ms=delay;const auto normal=b::make_plan(19),changed=b::make_plan(19,custom);need(custom.valid()&&b::valid(changed),"Bounded custom Fish supply is a valid plan");
  for(unsigned i=0;i<normal.fights.size();++i){const auto& before=normal.fights[i];const auto& after=changed.fights[i];need(before.number==after.number&&before.family==after.family&&before.variant==after.variant&&before.terrain==after.terrain&&before.count==after.count&&before.genie_companion==after.genie_companion&&before.purple_mask==after.purple_mask&&before.no_flowers==after.no_flowers&&before.no_egg_blocks==after.no_egg_blocks,"Fish supply customization consumes no RNG or encounter changes");
   need(after.birds==(after.family==b::Family::Fish?quota:before.birds)&&after.bird_respawn_ms==(after.family==b::Family::Fish?delay:before.bird_respawn_ms),"Only Fish quota/timing follow Fish settings; every other family stays unchanged");
   for(unsigned n=0;n<before.count;++n){const auto& a=before.members[n];const auto& z=after.members[n];need(a.kind==z.kind&&a.hits==z.hits&&a.scale==z.scale&&a.red==z.red&&a.purple==z.purple&&a.green==z.green,"Fish supply changes neither members nor their native colors or movement variants");}
  }
 }
 for(unsigned fault=0;fault<6;++fault){b::Config invalid;if(fault==0)invalid.fish_birds=0;if(fault==1)invalid.fish_birds=4;if(fault==2)invalid.fish_respawn_ms=0;if(fault==3)invalid.fish_respawn_ms=999;if(fault==4)invalid.fish_respawn_ms=60001;if(fault==5)invalid.fish_birds=~0u;need(!invalid.valid()&&!b::valid(b::make_plan(1,invalid)),"Unbounded or empty Fish supply cannot form a valid campaign");}
 for(unsigned fault=0;fault<5;++fault){auto tampered=b::make_plan(1);for(auto& fight:tampered.fights)if(fight.family==b::Family::Fish){if(fault==0)fight.birds=2;if(fault==1)fight.bird_respawn_ms=8000;if(fault==2)fight.birds=0;if(fault==3)fight.members[0].kind=0x4507;if(fault==4)fight.members[0].hits=3;break;}need(!b::valid(tampered),"Tampering Fish quota/timing/kind/HP bypasses neither config nor plan validation");}
 {auto special=b::make_plan(1);unsigned at=10;for(unsigned i=0;i<special.fights.size();++i)if(special.fights[i].family==b::Family::Fish){at=i;break;}need(at<10,"Guaranteed Fish fixture exists");auto& fish=special.fights[at];fish.members[0].kind=0x4511;fish.members[0].purple=false;fish.members[0].green=true;fish.purple_mask&=uint8_t(~1u);need(b::valid(special),"Explicit green vertical variant is valid only on a normal4511 member");auto invalid=special;invalid.fights[at].members[0].kind=0x4631;need(!b::valid(invalid),"Horizontal4631 cannot be marked green vertical");invalid=special;invalid.fights[at].members[0].purple=true;need(!b::valid(invalid),"One Fish cannot simultaneously be green and purple");invalid=special;invalid.fights[0].members[0].green=true;need(!b::valid(invalid),"Green flag cannot escape the Fish family");}
 c.more_birds=1;need(!c.valid()&&!b::valid(b::make_plan(1,c)),"invalid balance rejected");auto p=b::make_plan(1);p.fights[0].count=2;need(!b::valid(p),"first fight cannot gain companion");std::cout<<"BossBattle0250 "<<checks<<" checks passed\n";return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
